import re
POLICY = {"refund": {"max_amount": 300000, "needs": ["order_id", "amount"]}}
def guard(call, verified):
    p = POLICY.get(call["name"])
    if p is None:
        return "거절: 없는 도구"
    missing = [k for k in p["needs"] if k not in call["args"]]
    if missing:
        return "되묻기: " + ",".join(missing)
    if not verified:
        return "거절: 본인 확인 전"
    if call["args"]["amount"] > p["max_amount"]:
        return "사람에게 넘김: 한도 초과"
    return "실행"
print(guard({"name": "refund", "args": {"order_id": "A1", "amount": 50000}}, True))   # 실행
print(guard({"name": "refund", "args": {"order_id": "A1", "amount": 900000}}, True))  # 사람에게 넘김: 한도 초과
print(guard({"name": "refund", "args": {"order_id": "A1"}}, True))                    # 되묻기: amount
print(guard({"name": "refund", "args": {"order_id": "A1", "amount": 50000}}, False))  # 거절: 본인 확인 전
print(guard({"name": "delete_account", "args": {}}, True))                             # 거절: 없는 도구

def mask(text):
    text = re.sub(r"01[0-9]-?\d{3,4}-?\d{4}", "[전화번호]", text)
    text = re.sub(r"\d{6}-?[1-4]\d{6}", "[주민번호]", text)
    return text
print(mask("제 번호는 010-1234-5678 이고 주민번호는 900101-1234567 이에요"))
# 제 번호는 [전화번호] 이고 주민번호는 [주민번호] 이에요

gold = {"q1": {"d3"}, "q2": {"d7", "d1"}, "q3": {"d9"}}
ranked = {"q1": ["d3", "d2", "d5"], "q2": ["d4", "d1", "d8"], "q3": ["d2", "d6", "d5"]}
for k in (1, 3):
    r = sum(len(set(ranked[q][:k]) & g) / len(g) for q, g in gold.items()) / len(gold)
    print(f"recall@{k} = {r:.3f}")
# recall@1 = 0.333
# recall@3 = 0.500   -> q3 은 정답 문서를 아예 못 가져왔다. 생성 모델이 아무리 좋아도 못 고친다
